[
  {
    "title": "first-move-unexplained",
    "claim": "Image #2 explains HasanAbi’s tactic and labels the sticks STANCE and TECHNIQUE, but does not explain the stance-plus-technique combination described in Image #6.",
    "reason": "A new player sees FIGHT before receiving the instruction needed to perform a deliberate move.",
    "suggest": "Add “Hold a stance, then add a technique” directly above FIGHT, using the same terminology as the technique reference."
  },
  {
    "title": "separated-direction-labels",
    "claim": "Image #3 places direction-to-action mappings in a separate panel above the sticks, while the corresponding stick edges show only chevrons.",
    "reason": "Players must visually connect each legend entry to a different location while learning the controls.",
    "suggest": "Place each action label beside its corresponding stick direction, keeping the drag areas unobstructed and all labels at least 18 CSS px."
  },
  {
    "title": "rematch-only-choice",
    "claim": "Image #18 shows REMATCH and STARTING IN 8, but no visible control for declining another bout or ending the session.",
    "reason": "The result screen presents replay as the only explicit choice.",
    "suggest": "Add an “End session” button alongside REMATCH that cancels the pending start and returns to the pre-fight screen."
  },
  {
    "title": "settings-pause-unidentified",
    "claim": "Image #7 shows settings over the visible arena without a PAUSED indicator, and the still cannot establish whether the bout is suspended.",
    "reason": "Players need to know whether they can safely adjust settings without the opponent continuing to fight.",
    "suggest": "Check simulation ticks and the round timer while settings are open; if suspended, show “Bout paused,” and if not, implement suspension before displaying that label."
  },
  {
    "title": "control-font-size-unverified",
    "claim": "The action labels in Image #3 are visible, but their compliance with the 18 CSS px minimum cannot be determined from this screenshot alone.",
    "reason": "These labels carry essential instructions, and screenshot dimensions are not computed CSS font measurements.",
    "suggest": "Measure the labels’ computed font sizes at 390×844 and desktop widths; increase any below 18 CSS px and adjust wrapping or spacing rather than shrinking text."
  }
]
